/* mech-bridge.js - desbloqueio de MECANICA (custom) -- substitui o popup nativo Rh */
(function(){
  (function(){var st=document.createElement('style');st.textContent='#mechOverlay,#mechOverlay *{overflow:visible !important}#mechOverlay button{overflow:hidden !important}';document.head.appendChild(st);})();

  // ==== AJUSTES ====
  var TITLE = "Well done!";   // legenda (sinônimo de Congratulations)
  // =================
  var TPL='<div style="position:relative; width:360px; max-width:100%; padding-top:46px;">' +'<div style="position:absolute; z-index:5; top:-6px; left:50%; transform:translateX(-50%); width:100px; height:100px; display:flex; align-items:center; justify-content:center;">' +'<div style="position:absolute; width:150px; height:150px; background: conic-gradient(from 0deg, rgba(255,210,70,0.9) 0deg 8deg, transparent 8deg 30deg, rgba(255,210,70,0.9) 30deg 38deg, transparent 38deg 60deg, rgba(255,210,70,0.9) 60deg 68deg, transparent 68deg 90deg, rgba(255,210,70,0.9) 90deg 98deg, transparent 98deg 120deg, rgba(255,210,70,0.9) 120deg 128deg, transparent 128deg 150deg, rgba(255,210,70,0.9) 150deg 158deg, transparent 158deg 180deg, rgba(255,210,70,0.9) 180deg 188deg, transparent 188deg 210deg, rgba(255,210,70,0.9) 210deg 218deg, transparent 218deg 240deg, rgba(255,210,70,0.9) 240deg 248deg, transparent 248deg 270deg, rgba(255,210,70,0.9) 270deg 278deg, transparent 278deg 300deg, rgba(255,210,70,0.9) 300deg 308deg, transparent 308deg 330deg, rgba(255,210,70,0.9) 330deg 338deg, transparent 338deg 360deg); -webkit-mask: radial-gradient(circle, transparent 42px, #000 44px, #000 70px, transparent 74px); mask: radial-gradient(circle, transparent 42px, #000 44px, #000 70px, transparent 74px); opacity:0.85; animation: caRays 26s linear infinite;"></div>' +'<svg width="92" height="92" viewBox="0 0 64 64" style="display:block; filter: drop-shadow(0 4px 5px rgba(20,50,90,0.35)); animation: caPop 2.6s ease-in-out infinite;">' +'<path d="M32 3l8.2 16.6L58.5 22l-13.2 12.9L48.4 53 32 44.4 15.6 53l3.1-18.1L5.5 22l18.3-2.4z" fill="#ffd83b" stroke="#e6a90f" stroke-width="2.5" stroke-linejoin="round"></path>' +'<path d="M32 11l4.4 9 9.9 1.4-7.2 7 1.7 9.9L32 42.6z" fill="#fff" opacity="0.4"></path>' +'</svg>' +'</div>' +'<div class="mm-card" style="width:100%; max-width:360px;">' +'<button class="mm-close" onclick="window.__mechWin._continue()" aria-label="Close"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round"><line x1="5" y1="5" x2="19" y2="19"></line><line x1="19" y1="5" x2="5" y2="19"></line></svg></button>' +'<div class="mm-eyebrow" style="margin-top:20px;">Unlocked</div>' +'<div id="mechTitle" class="mm-title">Well done!</div>' +'<div class="mm-iconwrap"><div id="mechTile" class="mm-disc" style="--mm-halo:#d9f0d0; --mm-halo2:#bfe6b0; --mm-halo-in:rgba(60,150,45,.18); --mm-halo-out:rgba(60,150,45,.4);"></div></div>' +'<div style="text-align:center; font-weight:700; font-size:14px; color:#9aa4b5; margin:-6px 0 2px;">You have unlocked</div>' +'<div style="text-align:center; font-weight:800; font-size:22px; color:#3cb52c; margin-bottom:12px;"><span id="mechName">Arrows</span></div>' +'<div id="mechSub" class="mm-desc" style="margin-bottom:20px;">Explore the next level!</div>' +'<button class="mm-btn" onclick="window.__mechWin._continue()"><span class="amt">Continue</span></button>' +'</div>' +'</div>', KF="@keyframes caArrow { 0%,100% { transform: translate(-50%, calc(-50% - 2px)); } 50% { transform: translate(-50%, calc(-50% + 2px)); } }\n@keyframes caPop { 0%,100% { transform: scale(1); } 50% { transform: scale(1.04); } }\n@keyframes caRays { to { transform: rotate(360deg); } }", ICONS={"2": "data:image/png;base64,", "3": "data:image/png;base64,", "4": "data:image/png;base64,", "5": "data:image/png;base64,", "6": "data:image/png;base64,", "7": "data:image/png;base64,", "8": "data:image/png;base64,", "9": "data:image/png;base64,", "10": "data:image/png;base64,", "11": "data:image/png;base64,"};  // ICONS: id 2..11 (1=Arrows mantem a seta do design)
  var overlay=null, scene=null, defTileHTML=null, defTileCss=null;

  function ensureStyle(){
    if(document.getElementById('mechStyle'))return;
    var s=document.createElement('style'); s.id='mechStyle';
    s.textContent="@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;600;700;800&display=swap');"+KF;
    document.head.appendChild(s);
  }
  function ensureOverlay(){
    ensureStyle();
    if(overlay)return;
    overlay=document.createElement('div'); overlay.id='mechOverlay';
    overlay.className='mm-overlay';
    overlay.innerHTML='<div id="mechModal" style="position:relative; width:100%; max-width:360px;">'+TPL+'</div>';
    document.body.appendChild(overlay);
    var t=document.getElementById('mechTitle'); if(t)t.textContent=TITLE;
    var tile=document.getElementById('mechTile'); if(tile){defTileHTML=tile.innerHTML; defTileCss=tile.style.cssText;}
    window.addEventListener('resize',fitModal);
  }
  function fitModal(){
    var m=document.getElementById('mechModal');
    if(!m||!overlay||overlay.style.display==='none')return;
    m.style.transform='none';
    var vw=window.innerWidth,vh=window.innerHeight,w=m.offsetWidth,h=m.offsetHeight;
    var over=72,margin=14;
    var sc=Math.min(1,(vw-2*margin)/w,(vh-2*margin)/(h+2*over));
    m.style.transformOrigin='center center';
    m.style.transform='scale('+sc+')';
    /* mede o retangulo visual real (card + penachos) e empurra pra dentro */
    try{
      var r=m.getBoundingClientRect(),top=r.top,bot=r.bottom,els=m.querySelectorAll('*');
      for(var i=0;i<els.length;i++){var b=els[i].getBoundingClientRect();if(b.height>0){if(b.top<top)top=b.top;if(b.bottom>bot)bot=b.bottom;}}
      var dy=0;
      if(top<margin)dy=margin-top;else if(bot>vh-margin)dy=(vh-margin)-bot;
      if(bot-top>vh-2*margin)dy=margin-top; /* maior que a tela: ancora topo visivel */
      if(dy)m.style.transform='translateY('+dy+'px) scale('+sc+')';
    }catch(e){}
  }
  function setIcon(id){
    var tile=document.getElementById('mechTile'); if(!tile)return;
    if(ICONS[id]){                      // 2..11: icone proprio da mecanica
      tile.innerHTML='<img src="'+ICONS[id]+'" style="width:80px;height:80px;object-fit:contain;display:block;filter:drop-shadow(0 4px 5px rgba(20,60,20,0.35));">';
    }else{                               // id1 Arrows: seta dupla verde
      tile.innerHTML='<svg width="52" height="72" viewBox="0 0 40 104" style="display:block;filter:drop-shadow(0 3px 4px rgba(20,80,15,0.4));"><line x1="20" y1="16" x2="20" y2="88" stroke="#3cb52c" stroke-width="8" stroke-linecap="round"></line><path d="M20 4l14 18H6z" fill="#3cb52c"></path><path d="M20 100l14-18H6z" fill="#3cb52c"></path></svg>';
    }
  }
  function proceed(){
    if(overlay)overlay.style.display='none';
    var sc=scene; scene=null;
    if(!sc)return;
    try{ sc.newMechanicWindow=null; sc.isNewMechanicWindow=false; }catch(e){console.warn('mechWin proceed',e);}
  }
  window.__mechWin={
    open:function(s,id){
      scene=s; ensureOverlay();
      try{
        var name=s.langMngr.getText('newMechanicName'+id);
        var sub=(s.langMngr.getText('newMechanicDesc2')||'').replace(/\n/g,' ');
        var n=document.getElementById('mechName'); if(n&&name)n.textContent=name;
        var su=document.getElementById('mechSub'); if(su&&sub)su.textContent=sub;
      }catch(e){console.warn('mechWin text',e);}
      setIcon(id);
      try{ s.isNewMechanicWindow=true; s.newMechanicWindow={updatePos:function(){},deleteAll:function(){}}; }catch(e){}
      overlay.style.display='flex'; fitModal(); setTimeout(fitModal,60); setTimeout(fitModal,250);
    },
    _continue:function(){ proceed(); }
  };
})();
